function lessonCard(l,studyMode=false){const destination=studyMode===true?'study':'lesson';return '<article class="card lesson-card"><a href="#/'+destination+'/'+l.id+'">'+visual(l.free?'FREE INTRO':'LESSON '+l.sort_order,l.free?'blue':'dark')+'</a><div class="card-body"><p class="meta">'+esc(l.level)+' · '+l.duration+' min · '+esc(l.category)+' · '+esc(l.equipment||'Any support')+'</p><h3>'+esc(l.title)+'</h3><p class="meta">'+esc(l.teacher||'Svitlana Yurchak')+'</p><div class="row"><b>'+ (l.free?'FREE':money(l.price))+'</b><a class="btn btn-small btn-outline" href="#/'+destination+'/'+l.id+'">VIEW ↗</a></div></div></article>'}
function bundleCard(bundle){
 return '<article class="card bundle-card"><a href="#/bundle/'+bundle.id+'"><div class="bundle-visual"><div class="bundle-visual-tile">01</div><div class="bundle-visual-tile">02</div><div class="bundle-visual-tile">03</div></div></a><div class="card-body"><p class="eyebrow">BUNDLE · '+bundle.lesson_ids.length+' LESSONS</p><h3><a href="#/bundle/'+bundle.id+'">'+esc(bundle.title)+'</a></h3><p>'+esc(bundle.description)+'</p><div class="row"><span><s class="meta">'+money(bundle.original_price)+'</s> <b class="price">'+money(bundle.price)+'</b></span><button type="button" class="btn btn-red btn-small" data-cart-bundle="'+bundle.id+'">ADD TO BAG</button></div></div></article>';
}
function bundlePage(route){
 const id=Number(route.split('/')[1]),b=state.bundles.find(x=>x.id===id);
 if(!b)return layout(section('Bundle unavailable','<p>This bundle is no longer available.</p>'+btn('BACK TO CLASSES','shop')));
 const lessons=b.lesson_ids.map(id=>state.lessons.find(l=>l.id===id)).filter(Boolean);
 layout(section(esc(b.title),'<p class="eyebrow"><a href="#/shop">CLASSES</a> / '+esc(b.direction)+' / BUNDLE</p><div class="grid grid-2"><div>'+bundleCard(b)+'</div><div><p class="description">'+esc(b.description)+'</p><p class="eyebrow">'+lessons.length+' INCLUDED LESSONS</p><div class="stack">'+lessons.map(l=>'<a class="item-row row" href="#/lesson/'+l.id+'"><span>'+esc(l.title)+'</span><span>'+esc(l.level)+' · '+l.duration+' min ↗</span></a>').join('')+'</div><p class="description">One request grants access to every lesson in this bundle after independent payment confirmation.</p><button type="button" class="btn btn-red" data-cart-bundle="'+b.id+'">ADD COMPLETE BUNDLE TO BAG</button></div></div>','BUILD YOUR PRACTICE'));
}
function shop(){
 const q=new URLSearchParams(location.hash.split('?')[1]||'');
 const query={search:q.get('q')||'',category:q.get('category')||'',level:q.get('level')||'',kind:q.get('kind')||'',teacher:q.get('teacher')||'',equipment:q.get('equipment')||'',focus:q.get('focus')||'',duration:q.get('duration')||''};
 const categories=[...new Set([...state.lessons.map(x=>x.category),...state.bundles.map(x=>x.direction)].filter(Boolean))];
 const teachers=[...new Set(state.lessons.map(x=>x.teacher).filter(Boolean))];
 const equipment=[...new Set(state.lessons.map(x=>x.equipment).filter(Boolean))];
 const focuses=[...new Set(state.lessons.flatMap(x=>(x.focus||'').split(',').map(v=>v.trim())).filter(Boolean))];
 const active=Object.values(query).some(Boolean);
 const lessons=state.lessons.filter(l=>{
  const terms=(l.title+' '+l.category+' '+(l.tags||'')+' '+(l.teacher||'')).toLowerCase();
  return (!query.search||terms.includes(query.search.toLowerCase()))&&(!query.category||l.category===query.category)&&(!query.level||l.level===query.level)&&(!query.kind||l.kind===query.kind)&&(!query.teacher||l.teacher===query.teacher)&&(!query.equipment||l.equipment===query.equipment)&&(!query.focus||(l.focus||'').toLowerCase().includes(query.focus.toLowerCase()))&&(!query.duration||l.duration<=Number(query.duration));
 });
 const select=(id,label,values,selected,empty)=>'<div><label>'+label+'</label><select id="'+id+'"><option value="">'+empty+'</option>'+values.map(v=>'<option value="'+esc(v)+'" '+(selected===v?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></div>';
 const categoryMenu=select('filterCategory','Direction',categories,query.category,'All directions');
 const typeMenu=select('filterKind','Type',['Element','Preparation','Warm-up','Bundle'],query.kind,'All types');
 const levelMenu=select('filterLevel','Level',['Beginner','Intermediate','Advanced'],query.level,'All levels');
 const teacherMenu=select('filterTeacher','Teacher',teachers,query.teacher,'Any teacher');
 const equipmentMenu=select('filterEquipment','Equipment',equipment,query.equipment,'Any equipment');
 const focusMenu=select('filterFocus','Training focus',focuses,query.focus,'Any focus');
 const durationMenu=select('filterDuration','Maximum duration',['15','30','60'],query.duration,'Any duration');
 const filteredBundles=state.bundles.filter(b=>(!query.category||b.direction===query.category)&&(!query.kind||query.kind==='Bundle')&&(!query.search||(b.title+' '+b.description).toLowerCase().includes(query.search.toLowerCase()))&&!query.level&&!query.teacher&&!query.equipment&&!query.focus&&!query.duration);
 const shelves=categories.map(category=>{
  const grouped=state.lessons.filter(l=>l.category===category);
  const types=[...new Set(grouped.map(l=>l.kind))];
  return '<div class="catalog-direction"><div class="row"><h2>'+esc(category).toUpperCase()+'</h2><a class="tiny-link" href="#/shop?category='+encodeURIComponent(category)+'">See all ↗</a></div>'+
   (state.bundles.some(b=>b.direction===category)?'<div class="shelf-head row"><h3>BUNDLES · ELEMENT + PREPARATION + WARM-UP</h3></div><div class="bundle-shelf">'+state.bundles.filter(b=>b.direction===category).map(bundleCard).join('')+'</div>':'')+types.map(kind=>{const group=grouped.filter(l=>l.kind===kind);return '<div class="shelf-head row"><h3>'+esc(kind)+'</h3><a href="#/shop?category='+encodeURIComponent(category)+'&kind='+encodeURIComponent(kind)+'">See all ↗</a></div><div class="lesson-shelf">'+group.map(lessonCard).join('')+'</div>'}).join('')+'</div>';
 }).join('');
 layout('<section class="section muted-section shop-heading"><div class="section-inner"><p class="eyebrow">THE MOVEMENT LIBRARY</p><h1>CLASSES</h1><p>Learn only what you need right now.</p></div></section><div class="strip" style="padding:18px 6%"><b>BUILD YOUR OWN PRACTICE · BUNDLES & INDIVIDUAL LESSONS</b></div>'+
 section('','<div class="shop-layout"><div class="filter-panel">'+categoryMenu+typeMenu+levelMenu+teacherMenu+equipmentMenu+focusMenu+durationMenu+'</div><div><input class="field" id="shopSearch" aria-label="Search lessons" placeholder="Search by title or hashtag (#kneecircle)…" value="'+esc(query.search)+'"><div class="pills">'+categories.map(x=>'<button class="pill '+(query.category===x?'active':'')+'" data-category="'+esc(x)+'">'+esc(x)+'</button>').join('')+(active?'<a class="pill" href="#/shop">Clear filters ✕</a>':'')+'</div>'+(active?'<p class="eyebrow">'+(lessons.length+filteredBundles.length)+' CLASSES FOUND</p><div class="grid grid-3">'+(lessons.map(lessonCard).join('')+filteredBundles.map(bundleCard).join('')||'<p>No lessons match these filters.</p>')+'</div>':shelves)+'</div></div>','')+
 '<div class="strip"><h2>WANT IT ALL? GET THE FULL COURSE.</h2>'+btn('SEE LEGWORK LAB','course','btn-white')+'</div>');
}
function lesson(route){const l=state.lessons.find(x=>x.id===getId(route));if(!l)return layout(section('Lesson not found','<p>Return to the library.</p>'+btn('CLASSES','shop')));layout(section('','<p class="eyebrow"><a href="#/shop">CLASSES</a> / '+esc(l.category)+' / '+esc(l.title)+'</p><div class="grid grid-2"><div>'+visual('LEARN · MOVE · REPEAT','blue')+'<p class="description">Video is provided only when you have access.</p></div><div><h1 style="font-size:clamp(2.6rem,5vw,5rem)">'+esc(l.title)+'</h1><p>'+esc(l.level)+' · '+l.duration+' minutes · '+esc(l.category)+'</p><p class="price">'+(l.free?'FREE':money(l.price))+'</p><div class="row"><button class="btn btn-red" data-watch="'+l.id+'">WATCH LESSON ▶</button>'+(l.free?'':'<button class="btn btn-outline" data-cart="'+l.id+'">ADD TO BAG</button>')+'</div><p class="description">Practice guidance and downloadable materials will be published by your teacher.</p></div></div><div id="playerMount" style="margin-top:35px"></div>','LESSON DETAIL')+section('PART OF LEGWORK LAB','<p>Get access to the full program and a structured learning journey.</p>'+btn('EXPLORE THE COURSE','course'),'CONTINUE LEARNING','muted-section'))}
function mentorship(){
 layout('<section class="mentorship-hero"><div class="section-inner"><p class="eyebrow">PRIVATE MENTORSHIP · VIDEO REVIEW</p><h1>GET MENTOR-LEVEL FEEDBACK ON YOUR VIDEO</h1><p>Practical, detailed guidance from a professional dancer and coach. Understand what to refine and what to practice next.</p><a class="btn btn-red" href="#/mentorship#request">GET MY MENTORSHIP ↗</a></div></section>'+
 section('YOUR MENTOR','<div class="mentorship-intro"><div class="mentorship-intro-portrait"></div><div><h3>SVITLANA YURCHAK · ARTIST & COACH</h3><ul class="mentor-details"><li>Creator of the Flexi Legs technique</li><li>International workshops and PoleCon teaching</li><li>Experience as a championship judge</li></ul></div></div>','AN EXPERIENCED EYE')+
 section('CHOOSE THE LEVEL OF FEEDBACK','<div class="grid grid-2 mentorship-prices"><div class="price-card"><h3>BASIC</h3><p>Focused, actionable feedback on your dance video.</p><p class="price">PRICE TBC</p><ul><li>Personal technique review</li><li>Practical next steps</li><li>Response timeframe confirmed before payment</li></ul><a href="#/mentorship#request" class="btn btn-dark" data-package="Basic">CHOOSE BASIC</a></div><div class="price-card featured"><h3>DEEP</h3><p>An in-depth analysis focused on your dance goals and background.</p><p class="price">PRICE TBC</p><ul><li>Detailed video analysis</li><li>Personal recommendations</li><li>Extended questionnaire</li><li>Response timeframe confirmed before payment</li></ul><a href="#/mentorship#request" class="btn btn-red" data-package="Deep">CHOOSE DEEP</a></div></div>','TWO WAYS TO GROW','muted-section')+
 section('HOW IT WORKS','<div class="course-steps">'+['CHOOSE A PACKAGE','SHARE YOUR VIDEO','CONFIRM PAYMENT','GET YOUR FEEDBACK'].map((t,i)=>'<div class="course-step"><span>0'+(i+1)+'</span><strong>'+t+'</strong></div>').join('')+'</div>','SIMPLE AND PERSONAL')+
 section('AN EXAMPLE OF YOUR FEEDBACK','<div class="feedback-sample"><div class="feedback-sample-media"></div><div><h3>SVITLANA’S FEEDBACK</h3><p>Your private review will appear here after your mentor responds, alongside recommendations selected for your technique.</p><h3>RECOMMENDED FOR YOU</h3><div class="feedback-products"><a href="#/shop">BROWSE LESSON BUNDLES ↗</a><a href="#/shop">EXPLORE CLASSES ↗</a></div></div></div>','YOUR PERSONAL REVIEW')+
 '<section class="section muted-section" id="request"><div class="section-inner mentorship-request"><p class="eyebrow">REQUEST YOUR PERSONAL REVIEW</p><h2>LET’S WORK ON YOUR MOVEMENT.</h2><div class="auth-panel"><form class="form" id="mentorshipForm"><label>Package<select name="package" id="mentorshipPackage"><option>Basic</option><option>Deep</option></select></label><label>Video URL (Instagram / YouTube / Dropbox)<input class="field" required name="video_url" type="url" placeholder="https://"></label><label>Instagram username<input class="field" name="instagram" placeholder="@username"></label><label>What do you want to improve?<textarea rows="4" name="goals"></textarea></label><div class="stack hidden" id="deepFields"><label>Experience<textarea rows="3" name="experience" placeholder="Tell us about your dance background"></textarea></label><label>How often do you train?<select name="training_frequency"><option value="">Select</option><option>Once a week</option><option>2–3 times a week</option><option>4+ times a week</option></select></label><label>Do you teach dance?<select name="teaching"><option value="">Select</option><option>No</option><option>Yes</option></select></label></div><p class="notice">Request only — online payment and file uploads are not enabled yet. No money will be charged.</p><button class="btn btn-red" type="submit">SEND REQUEST ↗</button></form></div></div></section>'+
 section('YOUR QUESTIONS, ANSWERED',faq([['What kind of video can I send?','Send an accessible Instagram, YouTube or Dropbox link.'],['When will I receive feedback?','The response timeframe will be confirmed before payment is offered.'],['Is the review private?','Your request is visible only to authorized accounts. Check the privacy settings of your external video link.']]),'FAQ')+
 '<div class="strip"><h2>READY TO TAKE THE NEXT STEP?</h2><a class="btn btn-white" href="#/mentorship#request">CHOOSE YOUR MENTORSHIP ↗</a></div>');
 const chosen=sessionStorage.getItem('legwork_package')||'Basic';
 const sel=$('#mentorshipPackage');if(sel){sel.value=chosen;$('#deepFields')?.classList.toggle('hidden',chosen!=='Deep')}
}
function authPage(register=false){layout(section(register?'CREATE AN ACCOUNT':'WELCOME BACK','<div class="auth-panel"><form class="form" id="authForm"><input type="hidden" name="mode" value="'+(register?'register':'login')+'">'+(register?'<label>Full name<input class="field" required name="name" autocomplete="name"></label>':'')+'<label>'+ (register?'Email':'Email or Admin')+'<input class="field" required name="email" '+(register?'type="email"':'type="text"')+' autocomplete="username"></label><label>Password<input class="field" required type="password" name="password" minlength="'+(register?12:1)+'" autocomplete="'+(register?'new-password':'current-password')+'"></label><button class="btn btn-red" type="submit">'+(register?'SIGN UP':'LOG IN')+'</button><p class="description">'+(register?'Already have an account? <a href="#/login">Log in</a>':'New to the school? <a href="#/register">Create an account</a> · <a href="#/forgot-password">Forgot password?</a>')+'</p></form></div>','YOUR PERSONAL LEARNING SPACE','muted-section'))}
function forgotPasswordPage(){
 layout(section('RESET YOUR PASSWORD','<div class="auth-panel"><p class="description">Enter your account email. If the address is registered, we will send a secure reset link. The link expires in 30 minutes.</p><form id="forgotPasswordForm" class="form"><label>Email address<input class="field" type="email" name="email" autocomplete="email" required></label><button class="btn btn-red">SEND RESET LINK</button><a href="#/login">← Back to login</a></form></div>','ACCOUNT RECOVERY','muted-section'));
}
function resetPasswordPage(token){
 if(!/^[a-f0-9]{64}$/.test(token))return layout(section('INVALID RESET LINK','<p>This password reset link is invalid.</p>'+btn('REQUEST A NEW LINK','forgot-password')));
 layout(section('CHOOSE A NEW PASSWORD','<div class="auth-panel"><form id="resetPasswordForm" class="form"><label>New password (at least 12 characters)<input class="field" type="password" name="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label>Confirm new password<input class="field" type="password" name="confirm_password" autocomplete="new-password" minlength="12" maxlength="128" required></label><button class="btn btn-red">RESET PASSWORD</button></form></div>','SECURE ACCOUNT RECOVERY','muted-section'));
}
async function verifyEmailPage(token){
 if(!/^[a-f0-9]{64}$/.test(token))return layout(section('INVALID VERIFICATION LINK','<p>The link is invalid.</p>'+btn('MY ACCOUNT','account')));
 try{
  const r=await api('/auth/verify-email','POST',{token});
  layout(section('EMAIL CONFIRMED','<p class="description">'+esc(r.message)+'. You can now purchase courses and request mentorship.</p>'+btn('GO TO MY ACCOUNT','account'),'WELCOME TO LEGWORK','muted-section'));
 }catch(e){layout(section('VERIFICATION FAILED','<p class="description">'+esc(e.message)+'</p><p>Request another link from your account if this one has expired or has already been used.</p>'+btn('MY ACCOUNT','account'),'EMAIL CONFIRMATION','muted-section'))}
}

async function account(){if(!state.user)return authPage(false);const expectedHash=location.hash;const [d,achievement,homeworkReviews,paymentConfig,paymentHistory,emailStatus,certificateData]=await Promise.all([api('/dashboard'),api('/account/achievements'),api('/account/homework-reviews'),api('/payments/config'),api('/payments/mine'),api('/account/email-status'),api('/account/certificates')]);if(location.hash!==expectedHash)return;state.dashboard=d;const completed=d.progress.filter(x=>x.completed).length,owned=state.lessons.filter(l=>l.free||d.enrollments.some(c=>c.id===l.course_id)||d.lessonAccess.includes(l.id));const nextOwned=owned.find(l=>!d.progress.some(p=>p.lesson_id===l.id&&p.completed))||owned[0];const tab=state.tab;const nav=['overview','lessons','reviews','achievements','profile',...(state.user.role==='admin'?['admin']:[])];let body='';
if(tab==='overview'){
 const percent=owned.length?Math.round(completed/owned.length*100):0;
 const ownedCourses=d.enrollments.map(c=>'<a class="account-course" href="#/course"><div class="account-course-image"></div><div class="account-course-info"><h3>'+esc(c.title)+'</h3><span>'+(c.tier==='guru'?'GURU · WITH FEEDBACK':'SELF-PACED')+'</span><div class="progress-bar"><i style="width:'+percent+'%"></i></div><small>'+percent+'% COMPLETE</small></div></a>').join('');
 const feedbackSummary=d.mentorships.slice(0,2).map(m=>'<div class="account-feedback-entry"><div class="account-feedback-visual"></div><div><strong>'+esc(m.package)+' REVIEW</strong><p>'+esc(m.feedback||'Waiting for your mentor’s response.')+'</p><span class="badge-label">'+esc(m.status)+'</span></div></div>').join('')||'<p class="description">Your personal reviews will appear here. <a href="#/mentorship">Explore mentorship ↗</a></p>';
 body='<h2>HI, '+esc(state.user.name).toUpperCase()+'!</h2><div class="account-continue"><div class="account-continue-art"></div><div class="account-continue-content"><p class="eyebrow">CONTINUE YOUR PRACTICE</p><h3>'+(nextOwned?esc(nextOwned.title):'Your next lesson awaits')+'</h3><div class="progress-bar"><i style="width:'+percent+'%"></i></div><small>'+percent+'% OF ACCESSIBLE LESSONS COMPLETE</small></div>'+(nextOwned?'<a class="btn btn-red" href="#/study/'+nextOwned.id+'">CONTINUE ↗</a>':btn('EXPLORE LESSONS','shop'))+'</div>'+
 '<div class="account-section-head"><h3>MY COURSES & LESSONS</h3><button data-tab="lessons" class="tiny-link">VIEW ALL ↗</button></div><div class="grid grid-3 account-course-grid">'+(ownedCourses||'<p class="description">No courses purchased yet. <a href="#/course">Discover Legwork Lab ↗</a></p>')+'</div>'+
 '<div class="grid grid-2 account-panels"><div><div class="account-section-head"><h3>MY VIDEO REVIEWS</h3><button class="tiny-link" data-tab="reviews">VIEW ALL ↗</button></div>'+feedbackSummary+'</div><div><div class="account-section-head"><h3>ACHIEVEMENTS</h3><button class="tiny-link" data-tab="achievements">VIEW ALL ↗</button></div><div class="account-achievements"><div><strong>'+achievement.streak+'</strong><span>DAY STREAK</span></div><div><strong>'+achievement.badges.length+'</strong><span>TECHNIQUE BADGES</span></div><div><strong>'+achievement.completed+'</strong><span>LESSONS COMPLETED</span></div></div></div></div>'+
 '<div class="account-section-head"><h3>MY ORDERS</h3></div>'+(d.orders.map(o=>'<div class="item-row">'+esc(o.kind)+' #'+o.item_id+' · '+money(o.amount)+' · '+esc(o.plan||'self')+' · <b>'+esc(o.status)+'</b></div>').join('')||'<p class="description">No orders yet.</p>');
}
if(tab==='overview'&&emailStatus.verification_required&&!emailStatus.verified)body='<div class="notice" role="alert"><b>Confirm your email address</b><p>We sent a verification link to '+esc(emailStatus.email)+'. Verify your email before buying classes or requesting mentorship. The link expires after 24 hours.</p><button type="button" id="resendVerification" class="btn btn-outline btn-small">RESEND VERIFICATION EMAIL</button></div>'+body;
if(tab==='overview')body+='<h3 style="margin-top:36px">PAYMENT CHECKOUT</h3>'+orderSelectionMarkup(d.orders,paymentConfig)+'<h3 style="margin-top:32px">PAYMENT HISTORY</h3>'+paymentHistoryMarkup(paymentHistory.payments,paymentConfig);
if(tab==='lessons')body='<h2>MY LESSONS</h2><div class="grid grid-3">'+owned.map(l=>lessonCard(l,true)).join('')+'</div>';
if(tab==='reviews')body='<h2>MY VIDEO REVIEWS</h2>'+(d.mentorships.map(m=>'<div class="item-row"><span class="badge-label">'+esc(m.status)+'</span><h3>'+esc(m.package)+'</h3><a href="'+esc(m.video_url)+'" target="_blank" rel="noopener noreferrer">Your video ↗</a><p>'+esc(m.feedback||'Your mentor has not replied yet.')+'</p></div>').join('')||'<p class="empty">No mentorship requests yet. <a href="#/mentorship">Explore mentorship →</a></p>')+'<h3>HOMEWORK FEEDBACK</h3>'+(homeworkReviews.reviews.map(r=>'<div class="item-row"><h3>'+esc(r.title)+'</h3><p>'+esc(r.feedback)+'</p><p class="meta">'+esc(r.reviewed_at)+'</p></div>').join('')||'<p class="description">No homework reviews yet.</p>');
if(tab==='achievements')body='<h2>YOUR ACHIEVEMENTS</h2><div class="grid grid-3">'+card(achievement.completed+' lessons completed','Keep practicing, each session counts.','PROGRESS')+card(achievement.streak+' day streak','Open an accessible lesson or submit homework daily.','CONSISTENCY')+card(achievement.badges.length+' technique badges','Finish a lesson and attach homework to earn a badge.','BADGES')+'</div><h3>BADGE COLLECTION</h3><div class="grid grid-3">'+(achievement.badges.map(b=>card(b.title,'Unlocked','★ BADGE')).join('')||'<p>No badges yet.</p>')+'</div><h3>COURSE CERTIFICATES</h3>'+studentCertificatesMarkup(certificateData.certificates);
if(tab==='profile')body='<h2>PROFILE</h2><form class="form auth-panel" id="profileForm"><label>Your name<input name="name" class="field" required value="'+esc(state.user.name)+'"></label><label>Instagram username<input name="instagram" class="field" value="'+esc(state.user.instagram||'')+'"></label><label>Email<input class="field" disabled value="'+esc(state.user.email)+'"></label><button class="btn btn-red">SAVE PROFILE</button></form><h3 style="margin-top:35px">CHANGE PASSWORD</h3><form class="form auth-panel" id="passwordForm"><label>Current password<input class="field" type="password" autocomplete="current-password" name="current_password" required></label><label>New password (12+ characters)<input class="field" type="password" minlength="12" autocomplete="new-password" name="new_password" required></label><button class="btn btn-outline">CHANGE PASSWORD</button></form><button class="btn btn-outline" id="logout">LOG OUT</button>';
if(tab==='admin')body='<h2>ADMIN STUDIO</h2><p>Manage course access, lesson links and mentorship requests.</p><div id="adminMount"><p>Loading admin data…</p></div>';
layout('<div class="cabinet"><aside class="cabinet-nav">'+nav.map(n=>'<button data-tab="'+n+'" class="'+(n===tab?'active':'')+'">'+n.charAt(0).toUpperCase()+n.slice(1)+'</button>').join('')+'</aside><div class="cabinet-main">'+body+'</div></div>');if(tab==='admin')adminPanel()}
async function adminPanel(){try{const a=state.admin=await api('/admin/overview');$('#adminMount').innerHTML='<div class="grid grid-3">'+card(a.users.length+' USERS','Registered profiles','PEOPLE')+card(a.orders.filter(o=>o.status==='pending').length+' PENDING','Requires independent payment verification','ORDERS')+card(a.mentorships.filter(x=>x.status==='paid').length+' TO REVIEW','Paid requests awaiting feedback','MENTORSHIP')+'</div><h3>Purchase requests</h3><div class="stack">'+(a.orders.map(o=>'<div class="item-row row"><span>#'+o.id+' · '+esc(o.email)+' · '+esc(o.kind)+' '+o.item_id+' · '+money(o.amount)+' · '+o.status+'</span>'+(o.status==='pending'?'<button class="btn btn-small btn-outline" data-approve="'+o.id+'">APPROVE AFTER PAYMENT</button>':'')+'</div>').join('')||'<p>No orders yet.</p>')+'</div><h3>Give a student course access</h3><form id="enrollForm" class="form"><select name="user_id" required>'+a.users.filter(x=>x.role==='student').map(u=>'<option value="'+u.id+'">'+esc(u.email)+'</option>').join('')+'</select><select name="course_id">'+a.courses.map(c=>'<option value="'+c.id+'">'+esc(c.title)+'</option>').join('')+'</select><button class="btn btn-dark">GRANT ACCESS</button></form><h3>Add a course</h3><form id="courseForm" class="form"><input class="field" name="title" placeholder="Course title" required><input class="field" name="slug" placeholder="course-url-slug" required><textarea class="field" name="description" placeholder="Description"></textarea><input class="field" type="number" min="0" name="price" placeholder="Price in cents"><button class="btn btn-dark">ADD COURSE</button></form><h3>Add a lesson</h3><form id="lessonForm" class="form"><select name="course_id">'+a.courses.map(c=>'<option value="'+c.id+'">'+esc(c.title)+'</option>').join('')+'</select><input class="field" name="title" placeholder="Lesson title" required><input class="field" name="category" placeholder="Category" value="Legwork"><input class="field" name="level" placeholder="Level" value="Beginner"><input class="field" name="video_url" type="url" placeholder="Private lesson video URL"><input class="field" name="price" type="number" placeholder="Price in cents" min="0"><label><input name="free" type="checkbox"> Free lesson</label><button class="btn btn-dark">ADD LESSON</button></form><h3>Edit lesson videos</h3><div class="stack">'+a.lessons.map(l=>'<form class="item-row form" data-edit-lesson="'+l.id+'"><b>'+esc(l.title)+'</b><input class="field" type="url" name="video_url" value="'+esc(l.video_url||'')+'" placeholder="Video URL"><label><input type="checkbox" name="free" '+(l.free?'checked':'')+'> Free</label><button class="btn btn-small btn-outline">UPDATE LESSON</button></form>').join('')+'</div><h3>Mentorship reviews</h3><div class="stack">'+(a.mentorships.map(m=>'<div class="item-row"><h3>'+esc(m.package)+' · '+esc(m.email)+' · '+esc(m.status)+'</h3><p><a target="_blank" rel="noopener noreferrer" href="'+esc(m.video_url)+'">View video ↗</a></p><p>'+esc(m.goals)+'</p>'+(m.status==='awaiting_payment'?'<button class="btn btn-small btn-outline" data-pay="'+m.id+'">MARK PAYMENT VERIFIED</button>':'<form class="form" data-feedback="'+m.id+'"><textarea name="feedback" required>'+esc(m.feedback)+'</textarea><button class="btn btn-small btn-red">SEND FEEDBACK TO ACCOUNT</button></form>')+'</div>').join('')||'<p>No requests yet.</p>')+'</div>';await adminExtras(a);await adminBundlePanel(a);await adminPaymentPanel();await adminMailPanel();await adminCertificatePanel();await adminEditorialPanel();translatePage($('#adminMount'),state.lang)}catch(e){if($('#adminMount'))$('#adminMount').textContent=e.message}}

