 const editLessons='<h3>EDIT FULL LESSON DETAILS</h3><p class="description">Expand a lesson to change its name, category, level, duration, price and video.</p><div class="stack">'+a.lessons.map(l=>'<details class="item-row"><summary>'+esc(l.title)+'</summary><form class="form" data-lesson-full="'+l.id+'"><label>Title<input class="field" name="title" required value="'+esc(l.title)+'"></label><div class="grid grid-2"><label>Category<input class="field" name="category" required value="'+esc(l.category)+'"></label><label>Type<input class="field" name="kind" required value="'+esc(l.kind)+'"></label><label>Level<input class="field" name="level" required value="'+esc(l.level)+'"></label><label>Duration in minutes<input class="field" name="duration" type="number" min="1" max="600" required value="'+l.duration+'"></label></div><label>Price in cents<input class="field" name="price" type="number" min="0" required value="'+l.price+'"></label><div class="grid grid-2"><label>Teacher<input class="field" name="teacher" value="'+esc(l.teacher||'Svitlana Yurchak')+'"></label><label>Equipment<input class="field" name="equipment" value="'+esc(l.equipment||'Any support')+'"></label><label>Training focus (comma-separated)<input class="field" name="focus" placeholder="Feet, Strength" value="'+esc(l.focus||'')+'"></label><label>Hashtags (comma-separated)<input class="field" name="tags" placeholder="#kneecircle" value="'+esc(l.tags||'')+'"></label></div><label>Private video URL<input class="field" name="video_url" type="url" value="'+esc(l.video_url||'')+'"></label><label><input name="free" type="checkbox" '+(l.free?'checked':'')+'> Introductory free lesson (account required)</label><button class="btn btn-dark">SAVE LESSON</button></form></details>').join('')+'</div>';
 const homeworkCards='<h3>GURU HOMEWORK REVIEW QUEUE</h3><p class="description">Only assignments from students with the Guru package appear here.</p><div class="stack">'+(homework.homework.map(h=>'<div class="item-row"><p class="eyebrow">'+esc(h.course)+' · '+esc(h.email)+'</p><h3>'+esc(h.lesson)+'</h3><a href="'+esc(h.homework_url)+'" target="_blank" rel="noopener noreferrer">VIEW HOMEWORK ↗</a><p class="meta">'+(h.reviewed_at?'Answered: '+esc(h.reviewed_at):'Awaiting review')+'</p><form class="form" data-homework-review="'+h.user_id+'-'+h.lesson_id+'"><label>Feedback<textarea class="field" rows="4" name="feedback" required>'+esc(h.feedback||'')+'</textarea></label><button class="btn btn-red">SAVE FEEDBACK</button></form><div class="row" style="margin-top:12px"><span class="badge-label">'+(h.approved?'APPROVED':'AWAITING APPROVAL')+'</span>'+(h.feedback?'<button type="button" class="btn btn-outline btn-small" data-homework-approval="'+h.user_id+'-'+h.lesson_id+'" data-approved="'+(h.approved?'false':'true')+'">'+(h.approved?'REVOKE APPROVAL':'APPROVE HOMEWORK')+'</button>':'')+'</div></div>').join('')||'<p class="empty">No Guru homework submissions yet.</p>')+'</div>';
 const leadList='<h3>WAITLIST SIGNUPS</h3><div class="stack">'+(waitlist.entries.map(x=>'<div class="item-row row"><b>'+esc(x.email)+'</b><span>'+esc(x.purpose)+' · '+esc(x.consent_at)+'</span></div>').join('')||'<p class="description">No subscribers yet.</p>')+'</div>';
 root.insertAdjacentHTML('beforeend',editCourses+editLessons+homeworkCards+leadList);
